 "content": "def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    pts = [(r,c,grid[r][c]) for r in range(h) for c in range(w) if grid[r][c]]
    # Markers encode rays: 2 emits a horizontal 5-segment; 3 emits vertical
    # 5 then diagonal 4s; 1 emits a 5 segment toward the nearest marker.
    for r,c,v in pts:
        if v == 2:
            for dc in (-1,1):
                x=c+dc
                while 0 <= x < w and grid[r][x] == 0:
                    out[r][x]=5; x+=dc
        elif v == 3:
            # down ray: adjacent 5, then diagonal 4s
            if r+1<h and grid[r+1][c]==0: out[r+1][c]=5
            for k in range(2, min(h-r,w-c)+1):
                y,x=r+k,c+k
                if grid[y][x] != 0: break
                out[y][x]=4
        elif v == 1:
            others=[p for p in pts if p[2] != 1]
            if not others: continue
            rr,cc,_=min(others,key=lambda p:abs(p[0]-r)+abs(p[1]-c))
            if rr == r:
                for x in range(min(c,cc)+1,max(c,cc)):
                    if grid[r][x] == 0: out[r][x]=5
            elif cc == c:
                for y in range(min(r,rr)+1,max(r,rr)):
                    if grid[y][c] == 0: out[y][c]=5
    # 2 also sends diagonal 4 rays away from nearby 3s? inferred from example,
    # diagonal continuation follows the 3 marker's direction and is handled above.
    return out
